from contextlib import contextmanager
from typing import Optional


class ConnectionManager:
    def __init__(self, default_alias: Optional[str]):
        self._default_alias = default_alias
        self._current_connection = default_alias

    @contextmanager
    def with_connection(self, connection_alias: str):
        """Context manager for temporary connection switching"""
        old_connection = self._current_connection
        self._current_connection = connection_alias
        try:
            yield
        finally:
            self._current_connection = old_connection

    def get_connection(self) -> str:
        """Get current connection alias"""
        if self._current_connection is None:
            raise RuntimeError("No connection alias set. Pass connection='ALIAS' to the method.")
        return self._current_connection

    def set_default_connection(self, alias: str):
        """Set new default connection"""
        self._default_alias = alias
        self._current_connection = alias

    def get_default_connection(self) -> Optional[str]:
        """Get default connection alias"""
        return self._default_alias

    def __repr__(self):
        return f"ConnectionManager(default='{self._default_alias}', current='{self._current_connection}')"
